"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Last Map', 'author': 'Signature original', 'genre': 'Arctic Survival', 'chapters': [{'n': 1, 'title': 'The Call of the Wild', 'text': "The landing was rough — it always is — and the Amazon basin swallowed them whole: heat, noise, green. the guide Kofi grinned. 'Just like old times.' Taylor Brooks grinned back. Old times had nearly killed them twice.\n\nThey made camp under strange stars. a carved obelisk key pulsed on Taylor Brooks's chest. Somewhere out there, the mercenary Voss was moving. The race, Taylor Brooks thought, was already on. fortune favors the bold — time to prove it.\n\nTaylor Brooks was fixing an engine when a carved obelisk key arrived — by courier, no return address, with a note: 'You know what this is. Come to the Amazon basin. Hurry.' Taylor Brooks knew. Everyone in their line knew the legend."}, {'n': 2, 'title': 'Into the Green', 'text': "Three days into the Amazon basin, the trail went cold — and then hot: fresh boot prints, the mercenary Voss's mark, heading the same way. 'They're a day ahead,' the guide Kofi said, 'but they're heavy. We're fast.'\n\nAt dawn the markers led to the ruins: stone teeth in the jungle's jaw. Taylor Brooks stood at the gate with a carved obelisk key humming louder. 'Whatever happens,' Taylor Brooks said, 'we go together.'\n\nTaylor Brooks laughed, coughed river, and lived. That night they found the first marker — an ancient carving that matched a carved obelisk key exactly. The legend was real. It had always been real."}, {'n': 3, 'title': 'The Ruins', 'text': "Inside: wonders. the guide Kofi, the scholar at heart, wept at the murals. Taylor Brooks kept watch, because wonders in such places usually have teeth. They did: the floor was a trap, the walls were a trap, the air was a trap.\n\nThe ruins of the Amazon basin were a puzzle built by people who didn't want visitors. a carved obelisk key was the key — literally; it fit a slot in the great door, and the stone sighed open after a thousand years.\n\nthe mercenary Voss's team hit them in the treasure chamber — of course it was the treasure chamber — and the standoff was pure cinema: a carved obelisk key on its pedestal, two crews, one exit. 'Take it,' the mercenary Voss said, 'and die rich.'"}, {'n': 4, 'title': 'The Price of Gold', 'text': "The trek out was worse than the trek in: the mercenary Voss's backup team, the river rising, the guide Kofi feverish from a scratch that turned ugly. Taylor Brooks carried the guide Kofi and a carved obelisk key in turns, and learned what shoulders are for.\n\nThe backup team wasn't loyal — just paid. When Taylor Brooks offered them the truth about the mercenary Voss's promises (empty) versus a share of the legitimate expedition rights (real), they lowered their weapons. Money talks. Truth talks louder.\n\nthe mercenary Voss, bound and furious, offered everything: money, power, a share. Taylor Brooks listened politely and said no politely, which infuriated the mercenary Voss more than any insult. Some people can't be bought. Some treasures can't be sold."}, {'n': 5, 'title': 'The Real Treasure', 'text': "A kid asked Taylor Brooks if it was worth it — the danger, the lost years. Taylor Brooks thought of the river, the ruins, the guide Kofi's hand in the rapids. 'The thing,' Taylor Brooks said, 'was never the thing.'\n\nThey stood before a carved obelisk key one last time. It had started all this: the legend, the race, the ruin, the rescue. Taylor Brooks saluted it. Some doors, once opened, stay open forever.\n\nThe museum opening was black tie. Taylor Brooks wore boots. the guide Kofi, recovered and insufferable, wore a grin. a carved obelisk key sat behind glass, humming faintly, home at last among people who'd care for it."}, {'n': 6, 'title': 'Next Horizon', 'text': "the guide Kofi was packed before Taylor Brooks finished reading the note. 'Where to?' the guide Kofi asked. Taylor Brooks pointed at the map's edge, past the Amazon basin, past everything known. 'There,' Taylor Brooks said.\n\nTaylor Brooks took one last look at the Amazon basin, green and gold and dangerous. It had given them a carved obelisk key, and taken nothing they weren't willing to give. Fair trade.\n\nEngines up. fortune favors the bold. The horizon, as always, was just the beginning."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

